MOD = 10**9 + 7

def count_valid_permutations(n, a, b, d):
    zeros = d.count(0)
    return pow(2, zeros, MOD)

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
        d = list(map(int, input().split()))
        results.append(count_valid_permutations(n, a, b, d))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
